def comps(grid,color):
 seen=set();cs=[]
 for r in range(len(grid)):
  for c in range(len(grid[0])):
   if grid[r][c]!=color or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c));co=[]
   while q:
    p=q.pop();co.append(p)
    for n in adj(*p):
     if grid[n[0]][n[1]]==color and n not in seen:seen.add(n);q.append(n)
   cs.append(co)
 return sorted(cs,key=len,reverse=True)
